void OnActionBegin(ActionBeginEventArgs args) {
    if (args.EventName == "load" && args.Query != null) {
        // Add extra filter to query
        args.Query.AddParams("onlyActive", true);
    }
    if (args.EventName == "filtering" && ShouldPreventFilter(args.Query))
        args.Cancel = true;
}

void OnActionComplete(ActionCompleteEventArgs<MyType> args) {
    if (args.Cancel) {
        // Prevent binding
    } else if (args.EventName == "load") {
        ResultsView = args.Result.ToList();
    }
}

void OnActionComplete(ActionCompleteEventArgs args) {
    // Check for aggregates and act
    if (args.Aggregates != null) { DoAggregates(args.Aggregates); }
    // Results post-processing
    var extra = args.Actual;
}

void OnBeforeOpen(BeforeOpenEventArgs args)
{
    if (!UserHasPermission) args.Cancel = true;
}

void OnDataBound(DataBoundEventArgs args)
{
  LogCount(args.Items as IEnumerable<object>);
}

void OnFiltering(FilteringEventArgs args)
{
    if (args.Text is string filter && filter.Length < 2) args.Cancel = true;
    if (args.PreventDefaultAction) LogCustomFilter(filter);
}

void OnPopup(PopupEventArgs args)
{
    if (args.Cancel) LogPopupBlocked();
    else args.Popup.SetMaxHeight(300);
}

void OnSelect(SelectEventArgs<MyModel> args)
{
    if (!args.IsInteracted) return;
    LogSelected(args.ItemData);
}

void OnChange(ChangeEventArgs<string, MyItem> args)
{
    if (args.IsInteracted && args.Value != args.PreviousItemData?.Id)
        args.Cancel = true;
}

void OnSelectAll(SelectAllEventArgs<MyType> args) {
    if (args.IsChecked) {
        Console.WriteLine($"All values selected: {string.Join(",", args.ItemData ?? new List<MyType>())}");
    }
}

void OnChipSelected(ChipSelectedEventArgs<MyType> args) {
    // Use args.ChipData for downstream business logic
}

void MultiSelectChanged(MultiSelectChangeEventArgs<string[]> args)
{
  if (!args.IsInteracted) return;
  // Audit or react to change in args.Value vs args.OldValue
}

void OnRemove(RemoveEventArgs<MyType> args) {
    if (args.IsInteracted) {
        Console.WriteLine($"Removed: {args.ItemData}");
    }
}

void OnTagging(TaggingEventArgs<MyType> args) {
    if (args.ItemData?.SomeProp == "blocked") {
        args.Cancel = true; // prevent this tag from being created
    }
    args.SetClass = "e-important-tag"; // add highlight
}

// Example implementing IDropDowns in a custom component
