{
    public RenderFragment? NoRecordsTemplate { get; set; }
    public RenderFragment? ActionFailureTemplate { get; set; }
    public void UpdateChildProperties(object fieldValue) { /* Implementation */ }
    public async Task CallStateHasChangedAsync() { /* Implementation */ }
}

// Example using IVirtualList<T>
public class MyVirtualizedDropDown<T> : IVirtualList<T>
{
    public RenderFragment<T>? ItemTemplate { get; set; }
    public RenderFragment<ComposedItemModel<T>>? GroupTemplate { get; set; }
}

